-- SanibonaniSave integrated seed entry point; generated by scripts/generate_integrated_seed.ps1
-- Test identities use reserved seed domains; records are scoped to LIGHT-/SEED-/SIM-FLOWS- groups.
-- Scenario 4 injects a balance drift and repairs it immediately: every group ends ledger-consistent.
-- The last module is 90_SEED_INTEGRITY_GATE.sql, inside this transaction: a failed check rolls the seed back.
BEGIN;

-- =====================================================================
-- Integrated source: 10_SEED_HELPERS.sql
-- =====================================================================
-- ─────────────────────────────────────────────────────────────────────────────
-- SanibonaniSave — SEED HELPERS
-- Version: 1.0 (October 2026)
-- ─────────────────────────────────────────────────────────────────────────────
-- Every money RPC reached from a seed session is refused. The 20261029 [SEC_002] guards
-- authorise on auth.role() / auth.uid(), and a seed session — `supabase db reset`, the SQL
-- editor, `psql -f` — carries no JWT, so both read NULL and CONTRIBUTION_ACCESS_DENIED is
-- raised on the first row. Posting fixtures by impersonating service_role would mean forging
-- the claim the guards trust, so the seed posts them the way internal_post_contribution does
-- instead: the contributions row is the audit record, one ledger row carries its id as
-- transaction_id (the shape consolidate_group_ledger_v1 reconstructs), and the group balance
-- moves through the unguarded primitive.
--
-- pg_temp: created per session and dropped with it, so nothing lands in the schema and no
-- tier needs a delta before the seed can run. Call it schema-qualified — pg_temp is never
-- searched for function names.
--
-- Run this module before any seed module that posts money
-- (MASTER_SEED_DATA.sql, 11_SEED_TEST_DATA_10_GROUPS_100_MEMBERS.sql,
-- 20_SEED_12_MONTHS_TRANSACTIONS.sql).
--
-- seed_post_loan_disbursement is the same rule for the other side of the ledger. A loan row is an
-- outflow the group has already paid, and consolidate_group_ledger_v1 block 4 reconstructs it as
-- -loans.amount under category 'loan_disbursement' keyed by the loan id. Inserting the loan without
-- booking that debit leaves the cached balance too high until a repair moves it (SYNC_DELTA_20261101B
-- P.4: six Local loans, R17,000). The helper books it at seed time, in the shape the reconstruction
-- produces, so the repair is a no-op; and it refuses a loan the group cannot cover, because a fixture
-- that only exists while nobody reconciles is the defect that delta was written to expose.
-- ─────────────────────────────────────────────────────────────────────────────

CREATE OR REPLACE FUNCTION pg_temp.seed_post_contribution(
    p_member_id UUID,
    p_group_id UUID,
    p_amount NUMERIC,
    p_due_date DATE,
    p_paid_at TIMESTAMPTZ,
    p_status TEXT,
    p_tx_id TEXT,
    p_type TEXT,
    p_member_name TEXT,
    p_description TEXT DEFAULT NULL
) RETURNS UUID
LANGUAGE plpgsql
AS $$
DECLARE
    v_contrib_id UUID;
    v_description TEXT := COALESCE(p_description, initcap(replace(p_type, '_', ' ')) || ' from ' || p_member_name);
BEGIN
    INSERT INTO public.contributions (member_id, group_id, amount, due_date, paid_at, status, transaction_id, type)
    VALUES (p_member_id, p_group_id, p_amount, p_due_date, p_paid_at, p_status, p_tx_id, p_type)
    RETURNING id INTO v_contrib_id;

    IF p_status IN ('paid', 'partial') THEN
        IF p_type IN ('member_fee', 'member_fee_ledger', 'registration_contribution') THEN
            -- Registration money is platform revenue: it never enters the group's ledger.
            INSERT INTO public.platform_ledger (transaction_id, amount, balance_after, description, category, group_id)
            VALUES (
                v_contrib_id::text,
                p_amount,
                (SELECT COALESCE(SUM(amount), 0) FROM public.platform_ledger) + p_amount,
                v_description,
                p_type,
                p_group_id
            );
        ELSE
            PERFORM public.increment_group_balance(
                p_group_id, p_amount, v_description, p_type, v_contrib_id::text, p_member_id
            );
        END IF;
    END IF;

    RETURN v_contrib_id;
END;
$$;

CREATE OR REPLACE FUNCTION pg_temp.seed_post_loan_disbursement(
    p_loan_id UUID,
    p_group_id UUID,
    p_member_id UUID,
    p_amount NUMERIC,
    p_member_name TEXT,
    p_at TIMESTAMPTZ DEFAULT NULL
) RETURNS VOID
LANGUAGE plpgsql
AS $$
DECLARE
    v_balance NUMERIC;
    v_at TIMESTAMPTZ := COALESCE(p_at, NOW());
BEGIN
    IF p_amount IS NULL OR p_amount <= 0 OR p_amount <> ROUND(p_amount, 2) THEN
        RAISE EXCEPTION '[FIN_003] INVALID_AMOUNT: Disbursement must be positive and have at most two decimal places';
    END IF;

    SELECT balance INTO v_balance FROM public.groups WHERE id = p_group_id FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION '[SYS_001] GROUP_NOT_FOUND: %', p_group_id;
    END IF;

    -- The loan id is the key the reconstruction uses, so a row already booked under it - by this
    -- helper on an earlier run, or by approve_and_disburse_loan_v1 - is the same money.
    IF EXISTS (SELECT 1 FROM public.group_ledger WHERE group_id = p_group_id AND transaction_id = p_loan_id::text) THEN
        RETURN;
    END IF;

    IF COALESCE(v_balance, 0) < p_amount THEN
        RAISE EXCEPTION '[FIN_002] SEED_LOAN_UNFUNDED: group % holds % but seeded loan % would disburse %',
            p_group_id, COALESCE(v_balance, 0), p_loan_id, p_amount;
    END IF;

    UPDATE public.groups
    SET balance = balance - p_amount, updated_at = NOW()
    WHERE id = p_group_id
    RETURNING balance INTO v_balance;

    INSERT INTO public.group_ledger (
        group_id, member_id, transaction_id, amount, balance_after, description, category, created_at
    ) VALUES (
        p_group_id, p_member_id, p_loan_id::text, -p_amount, v_balance,
        'Loan disbursement to ' || p_member_name, 'loan_disbursement', v_at
    );
END;
$$;

-- =====================================================================
-- Integrated source: MASTER_SEED_DATA.sql
-- =====================================================================
-- ─────────────────────────────────────────────────────────────────────────────
-- SanibonaniSave — MASTER SEED DATA (Consolidated)
-- Version: 3.1 (Money-Precise, Ledger-Safe Demo Environment - October 2026)
-- Self-contained except for pg_temp.seed_post_contribution, declared in 10_SEED_HELPERS.sql.
-- ─────────────────────────────────────────────────────────────────────────────

DO $$
DECLARE
    -- Actors
    v_admin_id UUID;
    v_member_id UUID;
    v_admin_member_id UUID;
    v_user_id UUID;
    v_group_id UUID;
    v_loan_id UUID;
    v_beneficiary_id UUID;
    v_poll_id UUID;
    v_repay_id UUID;
    v_member_name TEXT;
    v_now TIMESTAMPTZ := NOW();

    -- Development/demo credentials only
    v_qa_password TEXT := 'Pass123!';

    -- Platform admin credential: supplied out-of-band, NEVER committed. Set it in the same
    -- transaction before running this script:
    --     BEGIN;  SET LOCAL sanibonani.platform_admin_password = '<password>';  ... COMMIT;
    -- Unset behaviour: an existing admin keeps its current password; an admin created here
    -- has no usable password until supabase/maintenance/ROTATE_PLATFORM_ADMIN_PASSWORD_*.sql runs.
    v_admin_password TEXT := nullif(btrim(current_setting('sanibonani.platform_admin_password', true)), '');

    -- Config using Money-precise amounts (2 decimal scale via toPlainString)
    v_types TEXT ARRAY := ARRAY['burial_society', 'stokvel', 'rosca', 'investment_club', 'emergency_fund', 'community_savings', 'hybrid_savings_group', 'other'];
    v_providers TEXT ARRAY := ARRAY['sim_bank', 'yoco', 'stitch', 'nedbank', 'fnb', 'sim_bank', 'sim_bank', 'sim_bank'];
    v_provinces TEXT ARRAY := ARRAY['Gauteng', 'Western Cape', 'KwaZulu-Natal', 'Eastern Cape', 'Limpopo', 'Free State', 'Mpumalanga', 'North West'];
    v_cities TEXT ARRAY := ARRAY['Johannesburg', 'Cape Town', 'Durban', 'Gqeberha', 'Polokwane', 'Bloemfontein', 'Nelspruit', 'Rustenburg'];
    v_townships TEXT ARRAY := ARRAY['Soweto', 'Khayelitsha', 'Umlazi', 'Mdantsane', 'Seshego', 'Mangaung', 'Kanyamazane', 'Tlhabane'];
    v_lats FLOAT8 ARRAY := ARRAY[-26.2041, -33.9249, -29.8587, -33.9608, -23.8962, -29.0852, -25.4753, -25.8560];
    v_lons FLOAT8 ARRAY := ARRAY[28.0473, 18.4241, 31.0218, 25.6022, 29.4486, 26.1596, 30.9694, 25.6403];

    v_type TEXT;
    v_provider_id TEXT;
    v_group_name TEXT;
    v_email TEXT;
    v_full_name TEXT;
    v_idx INT;
    v_lat FLOAT8;
    v_lon FLOAT8;
    v_monthly_contrib_amount NUMERIC(12,2) := 500.00;  -- Money-precise (2-dp scale); matches Money domain precision
    v_joining_fee_amount NUMERIC(12,2) := 150.00;       -- Money-precise (2-dp scale); matches Money domain precision

    v_opt1_id UUID;
    v_opt2_id UUID;

BEGIN
    -- 1. IDENTIFY OR CREATE PLATFORM ADMIN
    SELECT id INTO v_admin_id FROM auth.users WHERE lower(email) = 'torrymsimango@gmail.com' LIMIT 1;
    IF v_admin_id IS NULL THEN
        v_admin_id := gen_random_uuid();
        INSERT INTO auth.users (id, instance_id, aud, role, email, encrypted_password, email_confirmed_at, raw_app_meta_data, raw_user_meta_data, created_at, updated_at)
        VALUES (v_admin_id, '00000000-0000-0000-0000-000000000000', 'authenticated', 'authenticated', 'torrymsimango@gmail.com',
                CASE WHEN v_admin_password IS NULL THEN NULL
                     ELSE extensions.crypt(v_admin_password, extensions.gen_salt('bf')) END,
                now(), '{"provider":"email","providers":["email"],"role":"platform_admin"}', '{"full_name":"Torry Msimango","role":"platform_admin"}', now(), now());
    ELSE
        UPDATE auth.users
        SET encrypted_password = CASE WHEN v_admin_password IS NULL THEN encrypted_password
                                      ELSE extensions.crypt(v_admin_password, extensions.gen_salt('bf')) END,
            raw_app_meta_data = '{"provider":"email","providers":["email"],"role":"platform_admin"}'::jsonb
        WHERE id = v_admin_id;
    END IF;

    IF v_admin_password IS NULL THEN
        RAISE NOTICE 'sanibonani.platform_admin_password is not set: an existing admin keeps its current password, a newly created one has none. Run supabase/maintenance/ROTATE_PLATFORM_ADMIN_PASSWORD_20261018.sql to set it.';
    END IF;

    INSERT INTO auth.identities (id, user_id, provider, provider_id, identity_data, created_at, updated_at)
    VALUES (gen_random_uuid(), v_admin_id, 'email', 'torrymsimango@gmail.com', jsonb_build_object('sub', v_admin_id, 'email', 'torrymsimango@gmail.com'), now(), now())
    ON CONFLICT (provider, provider_id) DO UPDATE SET user_id = EXCLUDED.user_id, identity_data = EXCLUDED.identity_data;

    INSERT INTO public.profiles (id, full_name, email, role)
    VALUES (v_admin_id, 'Torry Msimango', 'torrymsimango@gmail.com', 'platform_admin')
    ON CONFLICT (id) DO UPDATE SET role = 'platform_admin', full_name = 'Torry Msimango', email = 'torrymsimango@gmail.com';

    -- 2. CLEANUP (remove only rows owned by this seed; preserve the shared admin)
    RAISE NOTICE 'Starting Master Seeding Version 3.1...';
    -- platform_ledger.group_id is ON DELETE SET NULL, so the registration receipts these groups
    -- generated would survive their deletion and every re-run would stack another revenue history
    -- on the last one. Their transaction_id is the contribution row's id, which cascades away with
    -- the group, so a receipt with no contribution behind it is one of ours.
    DELETE FROM public.platform_ledger pl
    WHERE pl.group_id IN (
            SELECT id FROM public.groups
            WHERE name = ANY (ARRAY[
                'LIGHT-Burial Society', 'LIGHT-Stokvel', 'LIGHT-Rosca', 'LIGHT-Investment Club',
                'LIGHT-Emergency Fund', 'LIGHT-Community Savings', 'LIGHT-Hybrid Savings Group',
                'LIGHT-Other'
            ])
          )
       OR (pl.group_id IS NULL
           AND pl.category = 'registration_contribution'
           AND NOT EXISTS (
               SELECT 1 FROM public.contributions c WHERE c.id::text = pl.transaction_id
           ));

    DELETE FROM public.groups
    WHERE name = ANY (ARRAY[
        'LIGHT-Burial Society', 'LIGHT-Stokvel', 'LIGHT-Rosca', 'LIGHT-Investment Club',
        'LIGHT-Emergency Fund', 'LIGHT-Community Savings', 'LIGHT-Hybrid Savings Group',
        'LIGHT-Other'
    ]);
    DELETE FROM public.members
    WHERE email LIKE 'persona.%@master.example.com';
    DELETE FROM auth.users
    WHERE email LIKE 'persona.%@master.example.com'
      AND NOT EXISTS (SELECT 1 FROM public.groups g WHERE g.admin_user_id = auth.users.id);

    -- 3. TIER 1: CORE GROUPS (8 Types) with Money-precise financial seeding
    FOR v_idx IN 1..8 LOOP
        v_type := v_types[v_idx];
        v_provider_id := v_providers[v_idx];
        v_lat := v_lats[v_idx];
        v_lon := v_lons[v_idx];
        v_group_name := 'LIGHT-' || initcap(replace(v_type, '_', ' '));

        -- Create Group (Triggers handle metadata)
        INSERT INTO public.groups (
            name, type, province, city, township, description,
            joining_fee, monthly_contribution, balance,
            admin_user_id, fee_status, registration_paid,
            financial_provider_id, latitude, longitude
        ) VALUES (
            v_group_name, v_type, v_provinces[v_idx], v_cities[v_idx], v_townships[v_idx], 'Authoritative group for ' || v_type || ' testing.',
            v_joining_fee_amount, v_monthly_contrib_amount, 0.00,
            v_admin_id, 'paid', TRUE,
            v_provider_id, v_lat, v_lon
        ) RETURNING id INTO v_group_id;

        -- Update Admin Member (Torry)
        v_member_id := (SELECT id FROM public.members WHERE group_id = v_group_id AND user_id = v_admin_id LIMIT 1);
        UPDATE public.members
        SET full_name = 'Seed Admin (' || initcap(v_type) || ')',
            email = 'platform.admin@master.example.com',
            bank_name = 'Standard Bank',
            account_no = '1234567890',
            branch_code = '051001'
        WHERE id = v_member_id;
        v_admin_member_id := v_member_id;

        -- 🛡️ Admin Financials - registration contribution, posted as a platform receipt
        SELECT full_name INTO v_member_name FROM public.members WHERE id = v_member_id;
        PERFORM pg_temp.seed_post_contribution(
            v_member_id, v_group_id, v_monthly_contrib_amount, v_now::date, v_now,
            'paid', 'REG-ADMIN-' || v_group_id, 'registration_contribution', v_member_name
        );

        -- Add 3 Persona Members
        FOR m IN 1..3 LOOP
            v_email := 'persona.' || v_idx || '.' || m || '@master.example.com';
            v_full_name := 'Member ' || m || ' (' || initcap(v_type) || ')';
            v_user_id := gen_random_uuid();

            -- Create Auth & Profile
            INSERT INTO auth.users (id, instance_id, aud, role, email, encrypted_password, email_confirmed_at, raw_app_meta_data, raw_user_meta_data, created_at, updated_at)
            VALUES (v_user_id, '00000000-0000-0000-0000-000000000000', 'authenticated', 'authenticated', v_email, extensions.crypt(v_qa_password, extensions.gen_salt('bf')), now(), '{"provider":"email","providers":["email"],"role":"member"}', jsonb_build_object('full_name', v_full_name, 'role', 'member'), now(), now());

            INSERT INTO public.profiles (id, full_name, email, role) VALUES (v_user_id, v_full_name, v_email, 'member');

            -- Register Member
            INSERT INTO public.members (
                group_id, user_id, full_name, email, status, joined_at, member_key,
                bank_name, account_no, branch_code, province, city, rosca_position
            ) VALUES (
                v_group_id, v_user_id, v_full_name, v_email,
                'active',
                v_now - interval '12 months', 'K-' || v_group_id || '-' || m,
                'FNB', '9876543210', '250655', v_provinces[v_idx], v_cities[v_idx],
                CASE WHEN v_type = 'rosca' THEN m + 1 ELSE NULL END
            ) RETURNING id INTO v_member_id;

            INSERT INTO public.member_behavior_track (member_id, group_id, joined_at, last_activity_at)
            VALUES (v_member_id, v_group_id, v_now - interval '12 months', v_now)
            ON CONFLICT (member_id) DO NOTHING;

            -- 🛡️ Record Joining Fee (Principal)
            PERFORM pg_temp.seed_post_contribution(
                v_member_id, v_group_id, v_joining_fee_amount,
                (v_now - interval '12 months')::date, v_now - interval '12 months',
                'paid', 'JOIN-' || v_member_id, 'registration_contribution', v_full_name
            );

            -- Record 12 months of paid contributions
            FOR h IN 1..12 LOOP
                PERFORM pg_temp.seed_post_contribution(
                    v_member_id, v_group_id, v_monthly_contrib_amount,
                    (v_now - (h * 30 || ' days')::interval)::date,
                    v_now - (h * 30 || ' days')::interval,
                    'paid', 'HIST-' || v_member_id || '-' || h, 'contribution', v_full_name
                );
            END LOOP;

            -- 📈 Profit Injection (Investment Club only)
            IF v_type = 'investment_club' AND m = 1 THEN
                PERFORM public.increment_group_balance(
                    v_group_id, 
                    v_monthly_contrib_amount,              -- Money-precise NUMERIC
                    'Market Gains - Institutional Dividends', 
                    'investment_gain', 
                    'MASTER-GAIN-' || v_group_id,
                    v_member_id
                );
            END IF;

            -- 🛡️ Section 29: Audit Reports
            -- These are dynamic, no need to seed table, but we ensure enough data exists.

            -- 👵 Beneficiary Seeding (Burial Society only)
            IF v_type = 'burial_society' THEN
                INSERT INTO public.beneficiaries (group_id, member_id, full_name, is_over_65, relationship)
                VALUES (v_group_id, v_member_id, 'Relative of ' || v_full_name, (m = 2), 'Parent');

                -- Update member beneficiary count
                UPDATE public.members
                SET beneficiary_count = 1,
                    beneficiary_over_65_count = CASE WHEN m = 2 THEN 1 ELSE 0 END
                WHERE id = v_member_id;
            END IF;

            -- Governance Seeding (Only for first group)
            IF v_idx = 1 AND m = 1 THEN
                INSERT INTO public.group_polls (id, group_id, created_by_member_id, title, description, type, status, ends_at)
                VALUES (gen_random_uuid(), v_group_id, v_member_id, 'Increase Monthly Contribution?', 'Proposal to increase from R500 to R600 to build larger reserves.', 'financial', 'open', v_now + interval '7 days')
                RETURNING id INTO v_poll_id;

                INSERT INTO public.group_poll_options (id, poll_id, label, position) VALUES
                (gen_random_uuid(), v_poll_id, 'Yes, R600 is fair', 1)
                RETURNING id INTO v_opt1_id;

                INSERT INTO public.group_poll_options (id, poll_id, label, position) VALUES
                (gen_random_uuid(), v_poll_id, 'No, keep it at R500', 2);
            END IF;

            -- Vote Casting (m=2 votes on m=1's poll)
            IF v_idx = 1 AND m = 2 AND v_poll_id IS NOT NULL THEN
                INSERT INTO public.group_poll_votes (poll_id, option_id, member_id, group_id)
                VALUES (v_poll_id, v_opt1_id, v_member_id, v_group_id);
            END IF;

            -- Fraud Seeding (m=3 in group 4 - Investment Club)
            IF v_idx = 4 AND m = 3 THEN
                INSERT INTO public.fraud_detection_events (member_id, group_id, event_type, severity, details)
                VALUES (v_member_id, v_group_id, 'VELOCITY_CHECK_FAILED', 'HIGH', '{"reason": "Multiple large transactions within 1 hour", "amount": 5000.00}');

                UPDATE public.member_behavior_track
                SET suspicious_activity_count = 1, unusual_payment_patterns = TRUE, behavior_score = 45.0, fraud_risk_level = 'high', is_flagged_for_review = TRUE
                WHERE member_id = v_member_id;
            END IF;

            -- Escalated Claim Seeding (Burial Society)
            IF v_type = 'burial_society' AND m = 1 THEN
                SELECT id INTO v_beneficiary_id
                FROM public.beneficiaries
                WHERE member_id = v_member_id
                ORDER BY created_at DESC
                LIMIT 1;

                INSERT INTO public.beneficiary_payout_claims (
                    group_id, member_id, beneficiary_id, beneficiary_name, claim_amount,
                    cause_of_death, date_of_death, status, bank_name, account_no, branch_code, account_holder
                ) VALUES (
                    v_group_id, v_member_id, v_beneficiary_id, 'Relative of ' || v_full_name, 15000.00,
                    'Natural', (v_now - interval '10 days')::date, 'escalated', 'SimBank', '123', '250', 'M'
                );
            END IF;

        END LOOP;

        PERFORM public.recalculate_all_group_financials_v3(v_group_id);
    END LOOP;

    -- 4. LOAN SEEDING (Emergency Fund) - using increment_group_balance with Money format
    SELECT id INTO v_group_id FROM public.groups WHERE name = 'LIGHT-Emergency Fund';
    SELECT id INTO v_member_id FROM public.members WHERE group_id = v_group_id AND status = 'active' AND user_id IS NOT NULL ORDER BY created_at LIMIT 1;

    IF v_group_id IS NOT NULL AND v_member_id IS NOT NULL THEN
        -- Inject seed liquidity first
        PERFORM public.increment_group_balance(
            v_group_id, 
            v_monthly_contrib_amount, 
            'Seed Liquidity - Reserve Fund', 
            'adjustment',
            'SCEN-EMERGENCY-SEED', 
            v_member_id
        );

        INSERT INTO public.loans (
            member_id, group_id, amount, interest_rate, total_to_repay, total_repaid,
            monthly_repayment, start_date, end_date, status, purpose
        ) VALUES (
            v_member_id, v_group_id, 2000.00, 10.00, 2200.00, 500.00, 550.00,
            (v_now - interval '1 month')::date, (v_now + interval '3 months')::date, 'active', 'Medical Expense'
        ) RETURNING id INTO v_loan_id;

        SELECT full_name INTO v_member_name FROM public.members WHERE id = v_member_id;

        -- The loan above is money that left the group, so the ledger says so now instead of only
        -- after a repair. Same row consolidate_group_ledger_v1 block 4 would rebuild.
        PERFORM pg_temp.seed_post_loan_disbursement(
            v_loan_id, v_group_id, v_member_id, 2000.00, v_member_name,
            v_now - interval '1 month'
        );

        INSERT INTO public.loan_repayments (loan_id, member_id, group_id, amount, payment_method)
        VALUES (v_loan_id, v_member_id, v_group_id, 500.00, 'bank')
        RETURNING id INTO v_repay_id;

        PERFORM public.increment_group_balance(
            v_group_id, 500.00,
            'Loan repayment from ' || v_member_name,
            'loan_repayment', v_repay_id::text, v_member_id
        );
    END IF;

    RAISE NOTICE 'Master Seeding 3.1 complete: 8 core groups, 24 persona members, governance, claims, loan, and fraud demo data generated with Money-precise financial operations.';
END $$;

-- =====================================================================
-- Integrated source: 11_SEED_TEST_DATA_10_GROUPS_100_MEMBERS.sql
-- =====================================================================
-- ─────────────────────────────────────────────────────────────────────────────
-- SanibonaniSave — TEST DATA SEED (10 Groups / 100 Members)
-- Version: 6.1 (Money-Precise, Hybrid Co-op Inclusive - August 2026)
-- Self-contained except for pg_temp.seed_post_contribution, declared in 10_SEED_HELPERS.sql.
-- ─────────────────────────────────────────────────────────────────────────────

DO $$
DECLARE
    -- Constants
    v_qa_password TEXT := 'Pass123!';
    -- This fixture is NOT left on the shared QA password: it carries role='platform_admin', so
    -- is_platform_admin() answers for it and it can impersonate every group. Its credential is
    -- supplied out-of-band in the same transaction before this file runs:
    --     BEGIN;
    --     SET LOCAL sanibonani.seed_platform_admin_password = '<password>';
    --     ... run this file ...
    --     COMMIT;
    -- Unset behaviour mirrors 04_PLATFORM_ADMIN_SETUP.sql: an existing fixture keeps its current
    -- password (this file only ever creates the row, it never re-hashes one), and a fixture created
    -- here gets a NULL encrypted_password plus a NOTICE, so no rebuild can restore a published
    -- platform-admin credential.
    v_seed_admin_password TEXT := nullif(btrim(current_setting('sanibonani.seed_platform_admin_password', true)), '');
    v_now TIMESTAMPTZ := NOW();

    -- Arrays for randomization (includes Hybrid Savings Group)
    v_types TEXT ARRAY := ARRAY['burial_society', 'stokvel', 'rosca', 'investment_club', 'emergency_fund', 'community_savings', 'hybrid_savings_group', 'stokvel', 'burial_society', 'rosca'];
    v_group_names TEXT ARRAY := ARRAY['Eternal Peace Burial', 'Unity Savings Stokvel', 'Morning Star ROSCA', 'Blue Chip Investors', 'Crisis Response Fund', 'Neighborhood Savings', 'Ubuntu Hybrid Co-op', 'Friends of Soweto', 'Zion Funeral Society', 'Quick Turn ROSCA'];
    v_provinces TEXT ARRAY := ARRAY['Gauteng', 'Western Cape', 'KwaZulu-Natal', 'Eastern Cape', 'Limpopo', 'Free State', 'Mpumalanga', 'North West', 'Gauteng', 'Western Cape'];
    v_cities TEXT ARRAY := ARRAY['Johannesburg', 'Cape Town', 'Durban', 'Gqeberha', 'Polokwane', 'Bloemfontein', 'Nelspruit', 'Rustenburg', 'Pretoria', 'Stellenbosch'];
    v_banks TEXT ARRAY := ARRAY['First National Bank', 'Standard Bank', 'Absa Bank', 'Nedbank', 'Capitec Bank'];
    v_branch_codes TEXT ARRAY := ARRAY['250655', '051001', '632005', '198765', '470010'];

    -- Loop Variables
    v_admin_id UUID;
    v_group_id UUID;
    v_member_id UUID;
    v_loan_id UUID;
    v_user_id UUID;
    v_type TEXT;
    v_group_name TEXT;
    v_monthly_contrib_amount NUMERIC(12,2) := 500.00;   -- Money-precise (2-dp scale); matches Money domain precision
    v_joining_fee_amount NUMERIC(12,2) := 150.00;       -- Money-precise (2-dp scale); matches Money domain precision
    v_email TEXT;
    v_full_name TEXT;
    v_status TEXT;

BEGIN
    -- 1. IDENTIFY OR CREATE PLATFORM ADMIN
    SELECT id INTO v_admin_id FROM auth.users WHERE email = 'platform.admin@master.example.com' LIMIT 1;
    IF v_admin_id IS NULL THEN
        v_admin_id := gen_random_uuid();
        INSERT INTO auth.users (id, instance_id, aud, role, email, encrypted_password, email_confirmed_at, raw_app_meta_data, raw_user_meta_data, created_at, updated_at)
        VALUES (v_admin_id, '00000000-0000-0000-0000-000000000000', 'authenticated', 'authenticated', 'platform.admin@master.example.com', CASE WHEN v_seed_admin_password IS NULL THEN NULL ELSE extensions.crypt(v_seed_admin_password, extensions.gen_salt('bf', 10)) END, now(), '{"provider":"email","providers":["email"],"role":"platform_admin"}', '{"full_name":"Seed Platform Admin","role":"platform_admin"}', now(), now());

        INSERT INTO public.profiles (id, full_name, email, role)
        VALUES (v_admin_id, 'Seed Platform Admin', 'platform.admin@master.example.com', 'platform_admin');

        IF v_seed_admin_password IS NULL THEN
            RAISE NOTICE 'sanibonani.seed_platform_admin_password is not set: the seeded platform_admin fixture was created with no usable password. Set it with supabase/maintenance/ROTATE_PLATFORM_ADMIN_PASSWORD_20261018.sql (target platform.admin@master.example.com) or re-seed with the setting.';
        END IF;
    END IF;

    -- 2. CLEANUP (Targeted)
    RAISE NOTICE 'Seeding Fully Integrated Test Data (10 Groups / 100 Members with Hybrid Co-op)...';
    -- platform_ledger.group_id is ON DELETE SET NULL, so these groups' registration receipts would
    -- outlive them and stack a second revenue history on every re-run. Same rule as MASTER: a
    -- receipt with no contribution row behind it is one of ours.
    DELETE FROM public.platform_ledger pl
    WHERE pl.group_id IN (
            SELECT id FROM public.groups
            WHERE name = ANY (ARRAY[
                'SEED-Eternal Peace Burial', 'SEED-Unity Savings Stokvel', 'SEED-Morning Star ROSCA',
                'SEED-Blue Chip Investors', 'SEED-Crisis Response Fund', 'SEED-Neighborhood Savings',
                'SEED-Ubuntu Hybrid Co-op', 'SEED-Friends of Soweto', 'SEED-Zion Funeral Society',
                'SEED-Quick Turn ROSCA'
            ])
          )
       OR (pl.group_id IS NULL
           AND pl.category = 'registration_contribution'
           AND NOT EXISTS (
               SELECT 1 FROM public.contributions c WHERE c.id::text = pl.transaction_id
           ));

    DELETE FROM public.groups
    WHERE name = ANY (ARRAY[
        'SEED-Eternal Peace Burial', 'SEED-Unity Savings Stokvel', 'SEED-Morning Star ROSCA',
        'SEED-Blue Chip Investors', 'SEED-Crisis Response Fund', 'SEED-Neighborhood Savings',
        'SEED-Ubuntu Hybrid Co-op', 'SEED-Friends of Soweto', 'SEED-Zion Funeral Society',
        'SEED-Quick Turn ROSCA'
    ]);
    DELETE FROM auth.users WHERE email LIKE 'seed.member.%@example.com';

    -- 3. GENERATE 10 GROUPS
    FOR i IN 1..10 LOOP
        v_type := v_types[i];
        v_group_name := 'SEED-' || v_group_names[i];
        -- Investment Club gets R1000 monthly, all others R500
        IF v_type = 'investment_club' THEN
            v_monthly_contrib_amount := 1000.00;
        ELSE
            v_monthly_contrib_amount := 500.00;
        END IF;

        INSERT INTO public.groups (
            name, type, province, city, joining_fee, monthly_contribution,
            admin_user_id, fee_status, registration_paid, balance,
            bank_name, account_number, branch_code, created_at
        ) VALUES (
            v_group_name, v_type, v_provinces[i], v_cities[i], v_joining_fee_amount, v_monthly_contrib_amount,
            v_admin_id, 'paid', TRUE, 0.00,
            v_banks[(i % 5) + 1], '62' || (10000000 + i * 12345)::text, v_branch_codes[(i % 5) + 1],
            v_now - interval '12 months'
        ) RETURNING id INTO v_group_id;

        -- Admin is automatically added as member by trigger.
        UPDATE public.members
        SET joined_at = v_now - interval '12 months',
            status = 'active',
            bank_name = 'First National Bank',
            account_no = '62889900112',
            branch_code = '250655'
        WHERE group_id = v_group_id AND user_id = v_admin_id;

        -- 4. GENERATE 9 MEMBERS PER GROUP (Total 100 with admin)
        FOR m IN 1..9 LOOP
            v_email := 'seed.member.' || i || '.' || m || '@example.com';
            v_full_name := 'Seed Member ' || i || '-' || m;
            v_user_id := gen_random_uuid();
            v_status := 'active';

            -- Auth & Profile
            INSERT INTO auth.users (id, instance_id, aud, role, email, encrypted_password, email_confirmed_at, raw_app_meta_data, raw_user_meta_data, created_at, updated_at)
            VALUES (v_user_id, '00000000-0000-0000-0000-000000000000', 'authenticated', 'authenticated', v_email, extensions.crypt(v_qa_password, extensions.gen_salt('bf')), now(), '{"provider":"email","providers":["email"],"role":"member"}', jsonb_build_object('full_name', v_full_name, 'role', 'member'), now(), now());

            INSERT INTO public.profiles (id, full_name, email, role) VALUES (v_user_id, v_full_name, v_email, 'member');

            -- Member Record with Banking Details
            INSERT INTO public.members (
                group_id, user_id, full_name, email, status, joined_at,
                rosca_position, province, city,
                bank_name, account_no, branch_code
            ) VALUES (
                v_group_id, v_user_id, v_full_name, v_email, v_status, v_now - interval '12 months',
                CASE WHEN v_type = 'rosca' THEN m + 1 ELSE NULL END,
                v_provinces[i], v_cities[i],
                v_banks[(m % 5) + 1], '10' || (20000000 + i * 1000 + m * 321)::text, v_branch_codes[(m % 5) + 1]
            ) RETURNING id INTO v_member_id;

            INSERT INTO public.member_behavior_track (member_id, group_id, joined_at, last_activity_at)
            VALUES (v_member_id, v_group_id, v_now - interval '12 months', v_now)
            ON CONFLICT (member_id) DO NOTHING;

            -- Pay Joining Fee
            PERFORM pg_temp.seed_post_contribution(
                v_member_id, v_group_id, v_joining_fee_amount,
                (v_now - interval '12 months')::date, v_now - interval '12 months',
                'paid', 'SEED-JOIN-' || v_member_id, 'registration_contribution', v_full_name
            );

            -- 12 Months History (100% paid up)
            FOR h IN 1..12 LOOP
                PERFORM pg_temp.seed_post_contribution(
                    v_member_id, v_group_id, v_monthly_contrib_amount,
                    (v_now - (h * 30 || ' days')::interval)::date,
                    v_now - (h * 30 || ' days')::interval,
                    'paid', 'SEED-HIST-' || v_member_id || '-' || h, 'contribution', v_full_name
                );
            END LOOP;

            -- Beneficiary Seeding (Burial Society only)
            IF v_type = 'burial_society' THEN
                INSERT INTO public.beneficiaries (group_id, member_id, full_name, is_over_65, relationship)
                VALUES (v_group_id, v_member_id, 'Beneficiary of ' || v_full_name, (m % 3 = 0), 'Relative');

                UPDATE public.members
                SET beneficiary_count = 1,
                    beneficiary_over_65_count = CASE WHEN m % 3 = 0 THEN 1 ELSE 0 END
                WHERE id = v_member_id;
            END IF;

            -- Integrated Loan Seeding (stokvel, emergency_fund, hybrid_savings_group)
            IF m = 1 AND v_type IN ('stokvel', 'emergency_fund', 'hybrid_savings_group') THEN
                INSERT INTO public.loans (
                    member_id, group_id, amount, interest_rate, total_to_repay, total_repaid,
                    monthly_repayment, start_date, end_date, status, purpose, amortization_type
                ) VALUES (
                    v_member_id, v_group_id, 2000.00, 20.00, 2415.00, 805.00, 402.50,
                    (v_now - interval '3 months')::date, (v_now + interval '3 months')::date, 'active', 'Integrated Seed Loan', 'flat'
                ) RETURNING id INTO v_loan_id;

                -- 'active' is a loan the group has already paid out, so the debit is booked with it.
                PERFORM pg_temp.seed_post_loan_disbursement(
                    v_loan_id, v_group_id, v_member_id, 2000.00, v_full_name,
                    v_now - interval '3 months'
                );
            END IF;

            -- Integrated Burial Claim Seeding
            IF v_type = 'burial_society' AND m = 2 THEN
                INSERT INTO public.beneficiary_payout_claims (
                    group_id, member_id, beneficiary_id, beneficiary_name, claim_amount,
                    cause_of_death, date_of_death, status, bank_name, account_no, branch_code, account_holder
                ) VALUES (
                    v_group_id, v_member_id, gen_random_uuid(), 'Dependent of ' || v_full_name, 5000.00,
                    'Natural', (v_now - interval '5 days')::date, 'submitted', v_banks[(m % 5) + 1], '62' || (30000000 + m)::text, v_branch_codes[(m % 5) + 1], v_full_name
                );
            END IF;
        END LOOP;

        -- Emergency Fund Hardening
        IF v_type = 'emergency_fund' THEN
            -- Keyed by group: this is capital no source table describes, so the id is the only thing
            -- that keeps a second run of this module from booking the same R500 twice.
            PERFORM public.increment_group_balance(
                v_group_id, 
                v_monthly_contrib_amount, 
                'Seed Liquidity - Reserve Fund', 
                'adjustment',
                'SEED-LIQUIDITY-' || v_group_id
            );
        END IF;

        -- Investment Club & Hybrid Hardening
        IF v_type IN ('investment_club', 'hybrid_savings_group') THEN
            PERFORM public.increment_group_balance(
                v_group_id, 
                v_monthly_contrib_amount, 
                'Seed Gains - Market Performance', 
                'investment_gain',
                'SEED-GAIN-' || v_group_id
            );
        END IF;

        PERFORM public.recalculate_all_group_financials_v3(v_group_id);
    END LOOP;

    RAISE NOTICE 'Fully Updated Master Seeding with Hybrid Co-op Complete.';
END $$;

-- =====================================================================
-- Integrated source: 15_SEED_LIVE_PAYOUT_REQUESTS.sql
-- =====================================================================
-- ─────────────────────────────────────────────────────────────────────────────
-- SanibonaniSave — LIVE PAYOUT REQUESTS SEED FOR EXISTING DATA
-- Version: 1.0 (August 2026)
-- ─────────────────────────────────────────────────────────────────────────────

DO $$
DECLARE
    v_group_id UUID;
    v_member_id UUID;
    v_now TIMESTAMPTZ := NOW();
BEGIN
    RAISE NOTICE 'Seeding Live Payout Requests for Existing Seed Data...';

    FOR v_group_id, v_member_id IN
        SELECT g.id, m.id
        FROM public.groups g
        JOIN public.members m ON m.group_id = g.id
        WHERE g.name LIKE 'SEED-%' AND m.status = 'active'
        LIMIT 15
    LOOP
        IF NOT EXISTS (
            SELECT 1 FROM public.payouts
            WHERE group_id = v_group_id AND member_id = v_member_id
              AND description = 'Integrated seed payout request'
        ) THEN
        INSERT INTO public.payouts (
            group_id, member_id, amount, payout_type, status,
            bank_name, account_no, branch_code, description, created_at
        ) VALUES (
            v_group_id,
            v_member_id,
            (random() * 2000 + 500)::NUMERIC(10,2),
            CASE WHEN random() < 0.5 THEN 'standard' ELSE 'emergency' END,
            'pending',
            'First National Bank',
            '62' || floor(random() * 900000000 + 100000000)::TEXT,
            '250655',
            'Integrated seed payout request',
            v_now
        );
        END IF;
    END LOOP;

    RAISE NOTICE 'Live Payout Requests Seeding Complete.';
END $$;

-- =====================================================================
-- Integrated source: 16_SEED_50_PAYMENT_REQUESTS_AND_APPROVALS.sql
-- =====================================================================
-- ─────────────────────────────────────────────────────────────────────────────
-- SanibonaniSave — 50 PAYOUT REQUESTS & APPROVAL CONDITIONS SEED
-- Version: 1.0 (August 2026)
-- ─────────────────────────────────────────────────────────────────────────────

DO $$
DECLARE
    v_group_id UUID;
    v_member_id UUID;
    v_bank TEXT;
    v_acc TEXT;
    v_branch TEXT;
    v_payout_types TEXT[] := ARRAY['standard', 'emergency', 'annual', 'disinvestment', 'claim', 'rotation'];
    v_banks TEXT[] := ARRAY['First National Bank', 'Standard Bank', 'Absa Bank', 'Nedbank', 'Capitec Bank'];
    v_branch_codes TEXT[] := ARRAY['250655', '051001', '632005', '198765', '470010'];
    v_type TEXT;
    v_counter INT := 0;
    v_now TIMESTAMPTZ := NOW();
BEGIN
    RAISE NOTICE 'Seeding 50 Payout Requests & Approval Conditions...';

    -- Replace only rows owned by this seed. Never overwrite group balances or statuses.
    DELETE FROM public.payouts
    WHERE description LIKE 'Seeded % Payout Request #%'
      AND group_id IN (SELECT id FROM public.groups WHERE name LIKE 'SEED-%');

    -- 4. Generate 50 Payout Requests across SEED groups and members
    FOR v_member_id, v_group_id, v_bank, v_acc, v_branch IN
        SELECT m.id, m.group_id, m.bank_name, m.account_no, m.branch_code
        FROM public.members m
        JOIN public.groups g ON m.group_id = g.id
        WHERE g.name LIKE 'SEED-%'
        ORDER BY m.group_id, m.id
    LOOP
        v_counter := v_counter + 1;
        IF v_counter > 50 THEN
            EXIT;
        END IF;

        v_type := v_payout_types[(v_counter % 6) + 1];

        INSERT INTO public.payouts (
            group_id, member_id, amount, bank_name, account_no, branch_code,
            status, payout_type, description, supporting_document_status, created_at
        ) VALUES (
            v_group_id,
            v_member_id,
            (1000.00 + (v_counter * 50.00))::NUMERIC(12,2),
            COALESCE(v_bank, v_banks[(v_counter % 5) + 1]),
            COALESCE(v_acc, '62' || (10000000 + v_counter * 123)::text),
            COALESCE(v_branch, v_branch_codes[(v_counter % 5) + 1]),
            'pending',
            v_type,
            'Seeded ' || UPPER(v_type) || ' Payout Request #' || v_counter,
            'verified',
            v_now - (v_counter || ' hours')::interval
        );
    END LOOP;

    RAISE NOTICE 'Seeded 50 Payout Requests with Verified Approval Conditions.';
END $$;

-- =====================================================================
-- Integrated source: 17_SEED_PLATFORM_FINANCIAL_ESCALATIONS.sql
-- =====================================================================
-- ─────────────────────────────────────────────────────────────────────────────
-- SanibonaniSave — PLATFORM FINANCIAL ESCALATIONS & PENDING REQUESTS SEED
-- Version: 1.0 (August 2026)
-- ─────────────────────────────────────────────────────────────────────────────

DO $$
DECLARE
    v_group_id UUID;
    v_member_id UUID;
    v_now TIMESTAMPTZ := NOW();
    v_counter INT := 0;
BEGIN
    -- Seed cases are explicitly tagged and isolated to SEED groups.
    DELETE FROM public.payouts
    WHERE description LIKE 'Platform Escalation Payout Request #%'
      AND group_id IN (SELECT id FROM public.groups WHERE name LIKE 'SEED-%');

    FOR v_group_id, v_member_id IN
        SELECT g.id, m.id
        FROM public.groups g
        JOIN public.members m ON m.group_id = g.id
        WHERE g.name LIKE 'SEED-%'
        LIMIT 10
    LOOP
        v_counter := v_counter + 1;
        INSERT INTO public.payouts (
            group_id, member_id, amount, bank_name, account_no, branch_code,
            status, payout_type, description, supporting_document_status, created_at
        ) VALUES (
            v_group_id, v_member_id, (1500.00 + v_counter * 100.00)::NUMERIC(12,2),
            'First National Bank', '628899001' || v_counter, '250655',
            'pending', 'standard', 'Platform Escalation Payout Request #' || v_counter,
            'verified', v_now - (v_counter || ' hours')::interval
        );
    END LOOP;

    -- 3. Seed 5 Pending / Escalated Loan Requests
    DELETE FROM public.loans WHERE group_id IN (SELECT id FROM public.groups WHERE name LIKE 'SEED-%') AND purpose LIKE 'Seed Platform Escalation Loan #%';
    v_counter := 0;

    FOR v_group_id, v_member_id IN
        SELECT g.id, m.id
        FROM public.groups g
        JOIN public.members m ON m.group_id = g.id
        WHERE g.name LIKE 'SEED-%'
        LIMIT 5
    LOOP
        v_counter := v_counter + 1;
        INSERT INTO public.loans (
            group_id, member_id, amount, interest_rate, total_to_repay, total_repaid,
            monthly_repayment, start_date, end_date, status, purpose, amortization_type, created_at
        ) VALUES (
            v_group_id, v_member_id, (2000.00 + v_counter * 250.00)::NUMERIC(12,2),
            20.00, (2400.00 + v_counter * 300.00)::NUMERIC(12,2), 0.00,
            (800.00 + v_counter * 100.00)::NUMERIC(12,2),
            v_now::date, (v_now + interval '3 months')::date,
            'pending', 'Seed Platform Escalation Loan #' || v_counter, 'flat', v_now - (v_counter || ' hours')::interval
        );
    END LOOP;

    -- 4. Seed 5 Escalated Burial Claims
    DELETE FROM public.beneficiary_payout_claims
    WHERE notes LIKE 'Seed Platform Escalation Claim #%'
      AND group_id IN (SELECT id FROM public.groups WHERE name LIKE 'SEED-%');
    v_counter := 0;

    FOR v_group_id, v_member_id IN
        SELECT g.id, m.id
        FROM public.groups g
        JOIN public.members m ON m.group_id = g.id
        WHERE g.name LIKE 'SEED-%'
        LIMIT 5
    LOOP
        v_counter := v_counter + 1;
        INSERT INTO public.beneficiary_payout_claims (
            group_id, member_id, beneficiary_id, beneficiary_name, claim_amount,
            cause_of_death, date_of_death, status, bank_name, account_no, branch_code, account_holder, created_at, notes
        ) VALUES (
            v_group_id, v_member_id, gen_random_uuid(), 'Dependent Beneficiary #' || v_counter, 10000.00,
            'Natural', (v_now - interval '3 days')::date, 'escalated',
            'Standard Bank', '05123456' || v_counter, '051001', 'Claimant ' || v_counter,
            v_now - (v_counter || ' hours')::interval, 'Seed Platform Escalation Claim #' || v_counter
        );
    END LOOP;
END $$;

-- =====================================================================
-- Integrated source: 19_SEED_BURIAL_CLAIM_ESCALATIONS.sql
-- =====================================================================
-- ─────────────────────────────────────────────────────────────────────────────
-- SanibonaniSave — BURIAL SOCIETY CLAIM ESCALATIONS SEED
-- Version: 2.0 (August 2026)
-- ─────────────────────────────────────────────────────────────────────────────

DO $$
DECLARE
    v_now TIMESTAMPTZ := NOW();
    v_counter INT := 0;
    v_r RECORD;
BEGIN
    -- Generate scenarios only for explicitly owned demo groups. Do not change
    -- balances, suspension flags, member statuses, or claims for real groups. SIM-* is
    -- deliberately absent: those groups are created by the running app, and a seed fixture
    -- inside one survives to be re-booked against a balance the harness already spent.
    FOR v_r IN
        SELECT g.id AS group_id, m.id AS member_id, m.full_name AS member_name
        FROM public.groups g
        JOIN public.members m ON m.group_id = g.id
        WHERE g.type = 'burial_society'
          AND (g.name LIKE 'LIGHT-%' OR g.name LIKE 'SEED-%')
        ORDER BY g.name, m.id
        LIMIT 10
    LOOP
        v_counter := v_counter + 1;

        -- Check if an escalated claim already exists for this member to avoid duplicates
        IF NOT EXISTS (
            SELECT 1 FROM public.beneficiary_payout_claims
            WHERE member_id = v_r.member_id AND status = 'escalated'
              AND notes LIKE 'Integrated seed burial escalation #%'
        ) THEN
            INSERT INTO public.beneficiary_payout_claims (
                group_id, member_id, beneficiary_id, beneficiary_name, claim_amount,
                cause_of_death, date_of_death, status, bank_name, account_no, branch_code, account_holder, created_at, notes
            ) VALUES (
                v_r.group_id,
                v_r.member_id,
                gen_random_uuid(),
                'Dependent Relative #' || v_counter,
                (7500.00 + v_counter * 750.00)::NUMERIC(12,2),
                CASE WHEN v_counter % 2 = 0 THEN 'Natural' ELSE 'Accidental' END,
                (v_now - (v_counter || ' days')::interval)::date,
                'escalated',
                'First National Bank',
                '62889900' || v_counter,
                '250655',
                'Claimant Admin ' || v_counter,
                v_now - (v_counter || ' hours')::interval,
                'Integrated seed burial escalation #' || v_counter || ' requiring platform intervention.'
            );
        END IF;
    END LOOP;
END $$;

-- =====================================================================
-- Integrated source: 31_REAL_LIFE_INTEGRITY_SEEDS.sql
-- =====================================================================
-- ─────────────────────────────────────────────────────────────────────────────
-- SanibonaniSave — REAL-LIFE INTEGRITY SEEDS (Extreme Testing Scenarios)
-- Version: 2.1 (Money-Precise, Audit & Forensic Hardening - August 2026)
-- Scenario 4 injects a balance drift and repairs it via
-- recalculate_all_group_financials_v3 in the same run, so every seeded group ends with
-- balance == SUM(group_ledger.amount).
-- ─────────────────────────────────────────────────────────────────────────────

DO $$
DECLARE
    v_stokvel_id UUID;
    v_burial_id UUID;
    v_emergency_id UUID;
    v_member_id UUID;
    v_user_id UUID;
    v_loan_id UUID;
    v_now TIMESTAMPTZ := NOW();
    v_qa_password TEXT := 'Pass123!';
    v_report JSONB;

BEGIN
    RAISE NOTICE '🔥 Injecting Real-Life Integrity Scenarios (Money-Precise)...';

    -- Identify Target Groups
    SELECT id INTO v_stokvel_id FROM public.groups WHERE name = 'LIGHT-Stokvel' LIMIT 1;
    SELECT id INTO v_burial_id FROM public.groups WHERE name = 'LIGHT-Burial Society' LIMIT 1;
    SELECT id INTO v_emergency_id FROM public.groups WHERE name = 'LIGHT-Emergency Fund' LIMIT 1;

    IF v_stokvel_id IS NULL OR v_burial_id IS NULL OR v_emergency_id IS NULL THEN
        RAISE EXCEPTION 'Run MASTER_SEED_DATA.sql first; required LIGHT demo groups are missing.';
    END IF;

    -- Make this scenario seed repeatable without touching non-seed members.
    DELETE FROM public.members
    WHERE email IN ('risky.payer@scen.com', 'loan.defaulter@scen.com', 'claimant@scen.com');
    DELETE FROM auth.users
    WHERE email IN ('risky.payer@scen.com', 'loan.defaulter@scen.com', 'claimant@scen.com');
    DELETE FROM public.audit_logs
    WHERE action IN ('INTEGRITY_DRIFT_INJECTED', 'INTEGRITY_DRIFT_REPAIRED')
      AND target_group_id = v_stokvel_id;
    DELETE FROM public.reconciliations
    WHERE group_id = v_stokvel_id
      AND status = 'resolved'
      AND notes LIKE '%repaired a 1234.56 drift%';

    -- 1. SCENARIO: The "Risky Payer" (LIGHT-Stokvel)
    -- Purpose: Test behavior score tracking and "High Risk" flags in Audit.
    v_user_id := gen_random_uuid();
    INSERT INTO auth.users (id, instance_id, aud, role, email, encrypted_password, email_confirmed_at, raw_app_meta_data, raw_user_meta_data, created_at, updated_at)
    VALUES (v_user_id, '00000000-0000-0000-0000-000000000000', 'authenticated', 'authenticated', 'risky.payer@scen.com', extensions.crypt(v_qa_password, extensions.gen_salt('bf')), now(), '{"provider":"email","providers":["email"],"role":"member"}', '{"full_name":"Sibusiso Risk","role":"member"}', now(), now());
    INSERT INTO public.profiles (id, full_name, email, role) VALUES (v_user_id, 'Sibusiso Risk', 'risky.payer@scen.com', 'member');

    INSERT INTO public.members (group_id, user_id, full_name, email, status, joined_at, member_key)
    VALUES (v_stokvel_id, v_user_id, 'Sibusiso Risk', 'risky.payer@scen.com', 'active', v_now - interval '6 months', 'SCEN-RISK-1')
    RETURNING id INTO v_member_id;

    INSERT INTO public.member_behavior_track (member_id, group_id, joined_at, last_activity_at)
    VALUES (v_member_id, v_stokvel_id, v_now - interval '6 months', v_now)
    ON CONFLICT (member_id) DO NOTHING;

    -- Seed 3 Overdue contributions using Money-precise amounts
    INSERT INTO public.contributions (member_id, group_id, amount, due_date, status, type)
    VALUES
        (v_member_id, v_stokvel_id, 500.00, (v_now - interval '90 days')::date, 'overdue', 'contribution'),
        (v_member_id, v_stokvel_id, 500.00, (v_now - interval '60 days')::date, 'overdue', 'contribution'),
        (v_member_id, v_stokvel_id, 500.00, (v_now - interval '30 days')::date, 'overdue', 'contribution');

    -- Manually force behavior score down (Trigger normally handles this on update, but we ensure it here)
    UPDATE public.member_behavior_track
    SET behavior_score = 30.0,
        fraud_risk_level = 'high',
        overdue_count = 3,
        review_notes = 'Member has missed 3 consecutive payments. Flagged for audit.'
    WHERE member_id = v_member_id;


    -- 2. SCENARIO: The "Defaulted Loan" (LIGHT-Emergency Fund)
    -- Purpose: Test loan status transitions and outstanding debt reporting.
    v_user_id := gen_random_uuid();
    INSERT INTO auth.users (id, instance_id, aud, role, email, encrypted_password, email_confirmed_at, raw_app_meta_data, raw_user_meta_data, created_at, updated_at)
    VALUES (v_user_id, '00000000-0000-0000-0000-000000000000', 'authenticated', 'authenticated', 'loan.defaulter@scen.com', extensions.crypt(v_qa_password, extensions.gen_salt('bf')), now(), '{"provider":"email","providers":["email"],"role":"member"}', '{"full_name":"Lindiwe Debt","role":"member"}', now(), now());
    INSERT INTO public.profiles (id, full_name, email, role) VALUES (v_user_id, 'Lindiwe Debt', 'loan.defaulter@scen.com', 'member');

    INSERT INTO public.members (group_id, user_id, full_name, email, status, joined_at, member_key)
    VALUES (v_emergency_id, v_user_id, 'Lindiwe Debt', 'loan.defaulter@scen.com', 'active', v_now - interval '1 year', 'SCEN-DEBT-1')
    RETURNING id INTO v_member_id;

    INSERT INTO public.member_behavior_track (member_id, group_id, joined_at, last_activity_at)
    VALUES (v_member_id, v_emergency_id, v_now - interval '1 year', v_now)
    ON CONFLICT (member_id) DO NOTHING;

    -- 🛡️ Boost Group Liquidity (Institutional injection to satisfy 50% withdrawal rule)
    IF NOT EXISTS (
        SELECT 1 FROM public.group_ledger
        WHERE group_id = v_emergency_id
          AND (transaction_id = 'SCEN-EMERGENCY-GRANT'
               OR description = 'Seed Liquidity - Institutional Grant')
    ) THEN
        PERFORM public.increment_group_balance(
            v_emergency_id, 
            10000.00, 
            'Seed Liquidity - Institutional Grant',
            'adjustment',
            'SCEN-EMERGENCY-GRANT',
            v_member_id
        );
    END IF;

    INSERT INTO public.loans (member_id, group_id, amount, interest_rate, total_to_repay, total_repaid, monthly_repayment, start_date, end_date, status, purpose)
    VALUES (v_member_id, v_emergency_id, 5000.00, 15.00, 5750.00, 0.00, 479.17, (v_now - interval '4 months')::date, (v_now + interval '8 months')::date, 'overdue', 'Emergency Repairs')
    RETURNING id INTO v_loan_id;

    -- An overdue loan is a disbursement that happened four months ago, so the R10,000 grant above
    -- has to cover it now; the R5,000 debit is booked with the row instead of only appearing when
    -- someone reconstructs the ledger.
    PERFORM pg_temp.seed_post_loan_disbursement(
        v_loan_id, v_emergency_id, v_member_id, 5000.00, 'Lindiwe Debt',
        v_now - interval '4 months'
    );


    -- 3. SCENARIO: The "Escalated Claim" (LIGHT-Burial Society)
    -- Purpose: Test Platform Admin intervention workflow and claim limits.
    v_user_id := gen_random_uuid();
    INSERT INTO auth.users (id, instance_id, aud, role, email, encrypted_password, email_confirmed_at, raw_app_meta_data, raw_user_meta_data, created_at, updated_at)
    VALUES (v_user_id, '00000000-0000-0000-0000-000000000000', 'authenticated', 'authenticated', 'claimant@scen.com', extensions.crypt(v_qa_password, extensions.gen_salt('bf')), now(), '{"provider":"email","providers":["email"],"role":"member"}', '{"full_name":"John Claimant","role":"member"}', now(), now());
    INSERT INTO public.profiles (id, full_name, email, role) VALUES (v_user_id, 'John Claimant', 'claimant@scen.com', 'member');

    INSERT INTO public.members (group_id, user_id, full_name, email, status, joined_at, member_key)
    VALUES (v_burial_id, v_user_id, 'John Claimant', 'claimant@scen.com', 'active', v_now - interval '2 years', 'SCEN-CLAIM-1')
    RETURNING id INTO v_member_id;

    INSERT INTO public.member_behavior_track (member_id, group_id, joined_at, last_activity_at)
    VALUES (v_member_id, v_burial_id, v_now - interval '2 years', v_now)
    ON CONFLICT (member_id) DO NOTHING;

    INSERT INTO public.beneficiary_payout_claims (
        group_id, member_id, beneficiary_id, beneficiary_name, claim_amount,
        cause_of_death, date_of_death, status, bank_name, account_no, branch_code, account_holder, notes
    ) VALUES (
        v_burial_id, v_member_id, gen_random_uuid(), 'Late Relative', 25000.00,
        'Accident', (v_now - interval '5 days')::date, 'escalated', 'Capitec', '55667788', '470010', 'J Claimant', 'High-value claim requires platform review.'
    );


    -- 4. SCENARIO: "Financial Drift" Detection
    -- Purpose: Exercise forensic detection of an un-ledgered balance change. The drift is
    -- injected by bypassing increment_group_balance, then repaired in the same run through the
    -- canonical reconciliation RPC so the seed never leaves a group out of balance.
    UPDATE public.groups AS g
    SET balance = COALESCE((
        SELECT SUM(l.amount) FROM public.group_ledger AS l WHERE l.group_id = g.id
    ), 0) + 1234.56
    WHERE g.id = v_stokvel_id;

    INSERT INTO public.audit_logs (actor_id, target_group_id, action, details)
    VALUES ('system', v_stokvel_id, 'INTEGRITY_DRIFT_INJECTED', '{"amount": 1234.56, "reason": "Test forensic detection of un-ledgered balance changes."}');

    v_report := public.recalculate_all_group_financials_v3(v_stokvel_id);

    -- Close the discrepancy_found row the repair just recorded: the drift is a resolved fixture,
    -- not an open incident.
    UPDATE public.reconciliations
    SET status = 'resolved',
        notes = notes || ' Resolved during seeding after the drift fixture was verified.',
        updated_at = NOW()
    WHERE id = (v_report->'reconciliation_report'->>'id')::uuid;

    INSERT INTO public.audit_logs (actor_id, target_group_id, action, details)
    VALUES ('system', v_stokvel_id, 'INTEGRITY_DRIFT_REPAIRED', jsonb_build_object(
        'amount', 1234.56,
        'final_balance', v_report->>'final_balance',
        'reconciliation_id', v_report->'reconciliation_report'->>'id'
    ));

    -- Every scenario group now satisfies balance == SUM(group_ledger.amount).
    PERFORM public.recalculate_all_group_financials_v3(v_burial_id);
    PERFORM public.recalculate_all_group_financials_v3(v_emergency_id);

    RAISE NOTICE '🏁 Integrity Scenarios Injected. All groups reconcile to their ledgers.';
END $$;

-- =====================================================================
-- Integrated source: 20_SEED_12_MONTHS_TRANSACTIONS.sql
-- =====================================================================
-- ─────────────────────────────────────────────────────────────────────────────
-- SanibonaniSave — 12-MONTH TRANSACTION & LEDGER SEED DATA (Support & Sim Flows)
-- Version: 2.3 (October 2026)
-- Self-contained except for pg_temp.seed_post_contribution, declared in 10_SEED_HELPERS.sql.
-- ─────────────────────────────────────────────────────────────────────────────

DO $$
DECLARE
    v_now TIMESTAMPTZ := NOW();
    v_amount NUMERIC := 500.00;
    v_h INT;
    v_count INT;
    v_support_group_id UUID;
    v_support_member_id UUID;
    v_support_user_id UUID;
    v_qa_password TEXT := 'Pass123!';
    v_r_group RECORD;
    v_r_member RECORD;
BEGIN
    RAISE NOTICE 'Seeding 12 months of transaction data for all groups and support/sim-flow sessions...';

    -- 1. Explicitly ensure Support Mode simulation group (SIM-FLOWS-466557) exists with 12 months of transactions
    IF NOT EXISTS (SELECT 1 FROM public.groups WHERE name LIKE 'SIM-FLOWS-%') THEN
        v_support_user_id := gen_random_uuid();

        INSERT INTO auth.users (id, instance_id, aud, role, email, encrypted_password, email_confirmed_at, raw_app_meta_data, raw_user_meta_data, created_at, updated_at)
        VALUES (v_support_user_id, '00000000-0000-0000-0000-000000000000', 'authenticated', 'authenticated', 'sim.flow4@master.example.com', extensions.crypt(v_qa_password, extensions.gen_salt('bf')), now(), '{"provider":"email","providers":["email"],"role":"member"}', '{"full_name":"Sim Flow Member 4","role":"member"}', now(), now())
        ON CONFLICT (id) DO NOTHING;

        INSERT INTO public.profiles (id, full_name, email, role)
        VALUES (v_support_user_id, 'Sim Flow Member 4', 'sim.flow4@master.example.com', 'member')
        ON CONFLICT (id) DO NOTHING;

        INSERT INTO public.groups (
            name, type, province, city, township, description,
            joining_fee, monthly_contribution, balance, admin_user_id, fee_status, registration_paid
        ) VALUES (
            'SIM-FLOWS-466557', 'stokvel', 'Gauteng', 'Johannesburg', 'Soweto', 'Support Mode Simulation Group',
            150.00, 500.00, 0.00, v_support_user_id, 'paid', TRUE
        ) RETURNING id INTO v_support_group_id;

        INSERT INTO public.members (
            group_id, user_id, full_name, email, status, joined_at, member_key
        ) VALUES (
            v_support_group_id, v_support_user_id, 'Sim Flow Member 4', 'sim.flow4@master.example.com', 'active', now() - interval '1 year', 'SIM-MEMBER-4'
        )
        ON CONFLICT (group_id, user_id) DO NOTHING
        RETURNING id INTO v_support_member_id;

        IF v_support_member_id IS NULL THEN
            SELECT id INTO v_support_member_id FROM public.members WHERE group_id = v_support_group_id LIMIT 1;
        END IF;

        FOR v_h IN 1..12 LOOP
            PERFORM pg_temp.seed_post_contribution(
                v_support_member_id, v_support_group_id, v_amount,
                (v_now - (v_h * 30 || ' days')::interval)::date,
                v_now - (v_h * 30 || ' days')::interval,
                'paid', 'SIM-TX-' || v_support_member_id || '-' || v_h, 'contribution',
                'Sim Flow Member 4', 'Monthly Contribution - Month ' || (13 - v_h)
            );
        END LOOP;
    END IF;

    -- 2. Fill only this seed pack's demo groups; never add demo transactions
    -- to customer groups in a shared or production database.
    FOR v_r_group IN
        SELECT id, name FROM public.groups
        WHERE name LIKE 'LIGHT-%' OR name LIKE 'SEED-%' OR name LIKE 'SIM-FLOWS-%'
        ORDER BY name
    LOOP
        SELECT COUNT(*) INTO v_count FROM public.group_ledger WHERE group_id = v_r_group.id;

        IF v_count < 12 THEN
            FOR v_r_member IN SELECT id, full_name FROM public.members WHERE group_id = v_r_group.id AND status = 'active' LOOP
                FOR v_h IN 1..12 LOOP
                    PERFORM pg_temp.seed_post_contribution(
                        v_r_member.id, v_r_group.id, v_amount,
                        (v_now - (v_h * 30 || ' days')::interval)::date,
                        v_now - (v_h * 30 || ' days')::interval,
                        'paid', 'TX-12M-' || v_r_member.id || '-' || v_h, 'contribution',
                        v_r_member.full_name, 'Monthly Contribution - Month ' || (13 - v_h)
                    );
                END LOOP;
            END LOOP;

            -- Recalculate group balance
            BEGIN
                PERFORM public.recalculate_all_group_financials_v3(v_r_group.id);
            EXCEPTION WHEN OTHERS THEN
                NULL;
            END;
        END IF;
    END LOOP;

    RAISE NOTICE '12-month transaction and ledger seeding complete.';
END $$;

-- =====================================================================
-- Integrated source: 21_SEED_VALID_BURIAL_CLAIMS.sql
-- =====================================================================
-- ─────────────────────────────────────────────────────────────────────────────
-- SanibonaniSave — VALID BURIAL SOCIETY CLAIMS SEED
-- Version: 2.0 (October 2026)
-- ─────────────────────────────────────────────────────────────────────────────

DO $$
DECLARE
    v_now TIMESTAMPTZ := NOW();
    v_r RECORD;
    v_counter INT := 0;
    v_claim_amount NUMERIC;
    v_claim_id UUID;
    v_status TEXT;
    v_balance NUMERIC;
BEGIN
    FOR v_r IN
        SELECT g.id AS group_id, m.id AS member_id, m.full_name AS member_name, g.burial_claim_amount
        FROM public.groups g
        JOIN public.members m ON m.group_id = g.id
        WHERE g.type = 'burial_society'
          AND m.status = 'active'
          AND (g.name LIKE 'LIGHT-%' OR g.name LIKE 'SEED-%')
        ORDER BY g.name, m.joined_at
        LIMIT 15
    LOOP
        v_counter := v_counter + 1;

        -- Ensure member tenure is > 6 months to pass validation
        UPDATE public.members
        SET joined_at = v_now - interval '12 months'
        WHERE id = v_r.member_id;

        -- Insert valid submitted/approved burial claim
        IF NOT EXISTS (
            SELECT 1 FROM public.beneficiary_payout_claims
            WHERE member_id = v_r.member_id AND notes LIKE 'Valid simulation burial claim #%'
        ) THEN
            v_claim_amount := coalesce(v_r.burial_claim_amount, 10000.00);
            v_status := CASE WHEN v_counter % 3 = 0 THEN 'approved' WHEN v_counter % 3 = 1 THEN 'submitted' ELSE 'paid' END;

            -- A paid claim has to have paid. pay_burial_claim_v1 books it as a 'claim' debit keyed
            -- by the claim id, so a fixture marked paid without that row shows a settlement the
            -- ledger never saw. A group that cannot cover the claim keeps it approved instead.
            IF v_status = 'paid' THEN
                SELECT balance INTO v_balance FROM public.groups WHERE id = v_r.group_id FOR UPDATE;
                IF COALESCE(v_balance, 0) < v_claim_amount THEN
                    v_status := 'approved';
                END IF;
            END IF;

            INSERT INTO public.beneficiary_payout_claims (
                group_id, member_id, beneficiary_id, beneficiary_name, claim_amount,
                cause_of_death, date_of_death, status, bank_name, account_no, branch_code, account_holder, created_at, notes
            ) VALUES (
                v_r.group_id,
                v_r.member_id,
                gen_random_uuid(),
                'Spouse / Dependent of ' || v_r.member_name,
                v_claim_amount,
                'Natural',
                (v_now - interval '10 days')::date,
                v_status,
                'First National Bank',
                '62110022' || v_counter,
                '250655',
                v_r.member_name,
                v_now - interval '2 days',
                'Valid simulation burial claim #' || v_counter || ' satisfying all waiting period and reserve criteria.'
            ) RETURNING id INTO v_claim_id;

            IF v_status = 'paid' THEN
                PERFORM public.increment_group_balance(
                    v_r.group_id,
                    -v_claim_amount,
                    'Burial claim: Spouse / Dependent of ' || v_r.member_name,
                    'claim',
                    v_claim_id::text,
                    v_r.member_id
                );
            END IF;
        END IF;
    END LOOP;
END $$;

-- =====================================================================
-- Integrated source: 90_SEED_INTEGRITY_GATE.sql
-- =====================================================================
-- ─────────────────────────────────────────────────────────────────────────────
-- SanibonaniSave — SEED INTEGRITY GATE
-- Version: 1.0 (October 2026)
-- ─────────────────────────────────────────────────────────────────────────────
-- The last word on a seed run. Every check below is a statement about the money the
-- seed just wrote, and any one of them failing aborts the transaction, so a tier is
-- never left holding fixtures that add up only until the first repair.
--
-- Why a gate and not another probe: the seed posts through pg_temp.seed_post_contribution
-- and public.increment_group_balance, and a fixture row can be inserted beside those
-- writers (loans, claims, payouts are written directly). The 2026-10-31 Cloud
-- reconstruction (SYNC_DELTA_20261101B) is the proof: consolidate_group_ledger_v1
-- rebuilds a group ledger from five source tables, and every seeded outflow that had been
-- inserted without booking its ledger row turned into a debit the group could not cover -
-- six SIM-FLOWS-* at -R26,200.00 and LIGHT-Burial Society at -R1,050.00. Those balances
-- were "consistent" right after seeding because groups.balance agreed with a ledger that
-- simply did not contain the loan. A balance-vs-ledger check cannot see that; only a
-- source-coverage check can.
--
-- What the gate asserts, in one line each:
--   SEED_001  groups.balance = SUM(group_ledger.amount), for every group.
--   SEED_002  no group is in the red.
--   SEED_003  every source row that the live path would have booked has that exact ledger
--             row (same group, same transaction_id, same amount, same category), so a
--             reconstruction is a no-op rather than a rewrite.
--   SEED_004  every platform-type paid contribution has its platform_ledger revenue row.
--   SEED_005  no platform category ever sits in the group ledger.
--   SEED_006  no ledger row is anonymous: a NULL transaction_id cannot be de-duplicated,
--             so re-running the seed double-books it.
--   SEED_007  no ledger row has a blank category.
--
-- Deliberately NOT asserted:
--   * Ledger rows with no source row. Those are legitimate - record_liquidity_v1 exists
--     precisely because bank interest, dividends and an opening balance are money the group
--     has and no contributions/loans/payouts/claims row describes (02_FUNCTIONS_AND_TRIGGERS
--     .sql:2055). They are keyed, and SEED_002 is what catches them if a wipe-and-rebuild
--     ever drops them and leaves a group short.
--   * Descriptions. The live path decorates ('Loan disbursement to X (bank)'), the
--     reconstruction does not, so the text is not a comparable field. Amount and category are.
--
-- SEED_003 is a contract, not a snapshot: its expected CTE has to stay row-for-row equal to
-- consolidate_group_ledger_v1's five group-side blocks and to internal_post_contribution's
-- type split, or the gate and the repair function disagree about what the ledger should contain.
-- Both read contributions through COALESCE(type, 'contribution') and both replay 'partial'; that
-- was not true before 2026-11-01, when the function skipped 'partial' rows and the gate had to be
-- stricter than it in order to make the loss loud (SYNC_DELTA_20261101C).
--
-- Read-only. This module writes nothing, so it is safe to paste on any tier on its own, and
-- that is how it is run against an existing tier - as a check, not as part of a repair.
--
-- Where it is wired: SEED_ALL_DATA.sql (generate_integrated_seed.ps1 inlines it last, inside the
-- BEGIN/COMMIT the generated file opens), so a failing check rolls the whole seed back - that is
-- the fail-hard. In 00_REBUILD_ALL.sql it is applied through \i, which autocommits per file, so
-- there it reports and the \i run continues; psql needs ON_ERROR_STOP=1 to treat it as fatal.
-- ─────────────────────────────────────────────────────────────────────────────

DO $$
DECLARE
    v_bad  INT;
    v_list TEXT;
BEGIN
    -- SEED_001  The cached column must equal its own ledger.
    SELECT count(*) INTO v_bad
    FROM public.groups g
    WHERE g.balance <> COALESCE((SELECT sum(l.amount) FROM public.group_ledger l WHERE l.group_id = g.id), 0);

    IF v_bad > 0 THEN
        SELECT string_agg(x, ' | ' ORDER BY x) INTO v_list
        FROM (
            SELECT g.name || ': balance=' || g.balance || ' ledger=' ||
                   COALESCE((SELECT sum(l.amount) FROM public.group_ledger l WHERE l.group_id = g.id), 0) AS x
            FROM public.groups g
            WHERE g.balance <> COALESCE((SELECT sum(l.amount) FROM public.group_ledger l WHERE l.group_id = g.id), 0)
            ORDER BY 1
            LIMIT 8
        ) offenders;
        RAISE EXCEPTION '[SEED_001] BALANCE_BUCKET_MISMATCH: % group(s) where groups.balance <> SUM(group_ledger.amount): %', v_bad, v_list;
    END IF;

    -- SEED_002  A savings group cannot have spent more than it holds. A negative here means an
    --           outflow was booked against capital that no inflow row backs.
    SELECT count(*) INTO v_bad FROM public.groups WHERE balance < 0;

    IF v_bad > 0 THEN
        SELECT string_agg(x, ' | ' ORDER BY x) INTO v_list
        FROM (SELECT name || '=' || balance AS x FROM public.groups WHERE balance < 0 ORDER BY balance LIMIT 8) offenders;
        RAISE EXCEPTION '[SEED_002] NEGATIVE_BALANCE: % group(s) reconstructed in the red: %', v_bad, v_list;
    END IF;

    -- SEED_003  Source-coverage. The CTE is consolidate_group_ledger_v1's five blocks written as
    --           an expectation instead of an insert (02_FUNCTIONS_AND_TRIGGERS.sql:1887-1932), and
    --           the anti-join asks whether each one is already in the ledger with the right money
    --           and the right category. Contributions split by type because that is what
    --           internal_post_contribution does (02_FUNCTIONS_AND_TRIGGERS.sql:238), and the type is
    --           read through COALESCE for the same reason the function reads it that way: the CHECK
    --           on contributions.type admits NULL, while group_ledger.category cannot be NULL.
    WITH expected AS (
        SELECT c.group_id, c.id::text AS tx_id, c.amount,
               COALESCE(c.type, 'contribution') AS category,
               'contribution ' || c.id AS what
        FROM public.contributions c
        WHERE c.status IN ('paid', 'partial')
          AND COALESCE(c.type, 'contribution') NOT IN ('registration_contribution', 'member_fee', 'member_fee_ledger')
        UNION ALL
        SELECT lr.group_id, lr.id::text, lr.amount, 'loan_repayment', 'loan_repayment ' || lr.id
        FROM public.loan_repayments lr
        UNION ALL
        SELECT p.group_id, p.id::text, -p.amount, 'payout', 'payout ' || p.id
        FROM public.payouts p
        WHERE p.status = 'completed'
        UNION ALL
        SELECT loan.group_id, loan.id::text, -loan.amount, 'loan_disbursement', 'loan ' || loan.id
        FROM public.loans loan
        WHERE loan.status NOT IN ('pending', 'rejected', 'cancelled')
        UNION ALL
        SELECT bc.group_id, bc.id::text, -bc.claim_amount, 'claim', 'claim ' || bc.id
        FROM public.beneficiary_payout_claims bc
        WHERE bc.status = 'paid'
    )
    SELECT count(*) INTO v_bad
    FROM expected e
    WHERE NOT EXISTS (
        SELECT 1 FROM public.group_ledger l
        WHERE l.group_id = e.group_id
          AND l.transaction_id = e.tx_id
          AND l.amount = e.amount
          AND l.category IS NOT DISTINCT FROM e.category
    );

    IF v_bad > 0 THEN
        WITH expected AS (
            SELECT c.group_id, c.id::text AS tx_id, c.amount,
                   COALESCE(c.type, 'contribution') AS category,
                   g.name || ' wants ' || c.amount || ' as ' || COALESCE(c.type, 'contribution') || ' for contribution ' || c.id AS what
            FROM public.contributions c JOIN public.groups g ON g.id = c.group_id
            WHERE c.status IN ('paid', 'partial')
              AND COALESCE(c.type, 'contribution') NOT IN ('registration_contribution', 'member_fee', 'member_fee_ledger')
            UNION ALL
            SELECT lr.group_id, lr.id::text, lr.amount, 'loan_repayment',
                   'loan repayment ' || lr.id || ' of ' || lr.amount
            FROM public.loan_repayments lr
            UNION ALL
            SELECT p.group_id, p.id::text, -p.amount, 'payout',
                   'completed payout ' || p.id || ' of ' || p.amount
            FROM public.payouts p WHERE p.status = 'completed'
            UNION ALL
            SELECT loan.group_id, loan.id::text, -loan.amount, 'loan_disbursement',
                   g.name || ' has loan ' || loan.id || ' (' || loan.status || ') of ' || loan.amount || ' with no disbursement row'
            FROM public.loans loan JOIN public.groups g ON g.id = loan.group_id
            WHERE loan.status NOT IN ('pending', 'rejected', 'cancelled')
            UNION ALL
            SELECT bc.group_id, bc.id::text, -bc.claim_amount, 'claim',
                   g.name || ' has paid claim ' || bc.id || ' of ' || bc.claim_amount || ' with no claim row'
            FROM public.beneficiary_payout_claims bc JOIN public.groups g ON g.id = bc.group_id
            WHERE bc.status = 'paid'
        )
        SELECT string_agg(what, ' | ' ORDER BY what) INTO v_list
        FROM (
            SELECT e.what
            FROM expected e
            WHERE NOT EXISTS (
                SELECT 1 FROM public.group_ledger l
                WHERE l.group_id = e.group_id
                  AND l.transaction_id = e.tx_id
                  AND l.amount = e.amount
                  AND l.category IS NOT DISTINCT FROM e.category
            )
            ORDER BY e.what
            LIMIT 8
        ) offenders;
        RAISE EXCEPTION '[SEED_003] SOURCE_ENTRY_UNBOOKED: % source row(s) the ledger never saw, so a consolidate_group_ledger_v1 rebuild would move the balance: %', v_bad, v_list;
    END IF;

    -- SEED_004  Registration money is platform revenue. Cloud carried R21,100.00 of it in neither
    --           ledger (SYNC_DELTA_20261101B P.5) because the seed wrote the contribution row
    --           directly instead of posting it; the helper routes it, and this is the check that
    --           says so forever.
    SELECT count(*) INTO v_bad
    FROM public.contributions c
    WHERE c.status IN ('paid', 'partial')
      AND c.type IN ('registration_contribution', 'member_fee', 'member_fee_ledger')
      AND NOT EXISTS (SELECT 1 FROM public.platform_ledger pl WHERE pl.transaction_id = c.id::text);

    IF v_bad > 0 THEN
        SELECT string_agg(x, ' | ' ORDER BY x) INTO v_list
        FROM (
            SELECT c.type || ' ' || c.id || ' of ' || c.amount AS x
            FROM public.contributions c
            WHERE c.status IN ('paid', 'partial')
              AND c.type IN ('registration_contribution', 'member_fee', 'member_fee_ledger')
              AND NOT EXISTS (SELECT 1 FROM public.platform_ledger pl WHERE pl.transaction_id = c.id::text)
            ORDER BY 1
            LIMIT 8
        ) offenders;
        RAISE EXCEPTION '[SEED_004] PLATFORM_REVENUE_UNBOOKED: % platform-type contribution(s) with no platform_ledger row: %', v_bad, v_list;
    END IF;

    -- SEED_005  The mirror image: a platform category in the group ledger inflates group money by
    --           the platform's fee. This is what P.1.c of SYNC_DELTA_20261101B had to delete.
    SELECT count(*) INTO v_bad
    FROM public.group_ledger
    WHERE category IN ('registration_contribution', 'member_fee', 'member_fee_ledger');

    IF v_bad > 0 THEN
        SELECT string_agg(x, ' | ' ORDER BY x) INTO v_list
        FROM (
            SELECT g.name || ' has ' || l.category || ' ' || l.amount || ' (' || l.transaction_id || ')' AS x
            FROM public.group_ledger l JOIN public.groups g ON g.id = l.group_id
            WHERE l.category IN ('registration_contribution', 'member_fee', 'member_fee_ledger')
            ORDER BY 1
            LIMIT 8
        ) offenders;
        RAISE EXCEPTION '[SEED_005] PLATFORM_TYPE_IN_GROUP_LEDGER: % group ledger row(s) carry a platform-only category: %', v_bad, v_list;
    END IF;

    -- SEED_006  An anonymous ledger row has no idempotency key, so a second run of the module that
    --           wrote it books the money twice - increment_group_balance can only compare rows it
    --           can find by transaction_id (02_FUNCTIONS_AND_TRIGGERS.sql:100-114).
    SELECT count(*) INTO v_bad FROM public.group_ledger WHERE transaction_id IS NULL;

    IF v_bad > 0 THEN
        SELECT string_agg(x, ' | ' ORDER BY x) INTO v_list
        FROM (
            SELECT g.name || ': ' || l.category || ' ' || l.amount || ' (' || COALESCE(l.description, 'no description') || ')' AS x
            FROM public.group_ledger l JOIN public.groups g ON g.id = l.group_id
            WHERE l.transaction_id IS NULL
            ORDER BY 1
            LIMIT 8
        ) offenders;
        RAISE EXCEPTION '[SEED_006] UNKEYED_LEDGER_ENTRY: % group ledger row(s) have no transaction_id and cannot be de-duplicated: %', v_bad, v_list;
    END IF;

    -- SEED_007  group_ledger.category has no CHECK constraint by design - the vocabulary is what
    --           the writers pass (02_FUNCTIONS_AND_TRIGGERS.sql:2076). A blank is not a category.
    SELECT count(*) INTO v_bad FROM public.group_ledger WHERE category IS NULL OR BTRIM(category) = '';

    IF v_bad > 0 THEN
        RAISE EXCEPTION '[SEED_007] BLANK_LEDGER_CATEGORY: % group ledger row(s) have no category', v_bad;
    END IF;

    RAISE NOTICE 'SEED INTEGRITY GATE passed: % groups, ledger rows % of which % carry source-backed money, no drift, no negative balance.',
        (SELECT count(*) FROM public.groups),
        (SELECT count(*) FROM public.group_ledger),
        (SELECT count(*) FROM public.group_ledger l WHERE EXISTS (
            SELECT 1 FROM public.contributions c
            WHERE c.id::text = l.transaction_id AND c.group_id = l.group_id));
END $$;

COMMIT;
